-- ===========================================================================
-- Comprobacion final: ninguna ruta con letrero puede quedarse sin trazado.
-- ===========================================================================
DO $$
DECLARE faltan INTEGER;
BEGIN
    SELECT count(*) INTO faltan
      FROM routes
     WHERE sign_file IS NOT NULL AND path_geojson IS NULL;

    IF faltan > 0 THEN
        RAISE EXCEPTION 'Quedaron % rutas con letrero sin trazado', faltan;
    END IF;
END $$;
